// Kode ini dibuat otomatis dari cmdmenu.js (teks identik dengan versi Node).
package cmdmenu

const MainText = "📋 Daftar Perintah\n\nPilih kategori di bawah:"

type Cat struct{ Label, Text string }

var Order = []string{"set", "list", "pin", "help"}

var Cats = map[string]Cat{
	"set": {Label: "⚙️ Pengaturan", Text: "⚙️ Pengaturan\n\n.ping - Cek respons\n.id - ID kamu / user yang di-reply\n.stop - Hentikan proses yang sedang berjalan (mis. .svslot)\n.eid - Simpan emoji premium: ketik .eid lalu emoji premiumnya di pesan yang sama (mis. .eid ✅⭐🔒), atau reply pesan berisi emoji premium dengan .eid (tanpa keduanya = lihat daftar; .eid hapus <emoji>; .eid reset). Dipakai otomatis di semua pesan userbot, butuh akun Premium\n.addsudo - Beri akses perintah ke akun lain (reply / id / @username)\n.delsudo - Cabut akses sudo\n.sudolist - Daftar sudo\n.on (atau .akses) - Aktifkan pencatatan bet K/B di chat ini. Nama yang tidak ada di pin tetap masuk .list, diberi titik, tanpa P\n.off (atau .delakses) - Matikan pencatatan di chat ini (data lama tetap ada)\n.alert on/off - Balas tiap pik pemain yang tercatat dengan \"✅ Pik: K 22 @pemain\" (nama pemain di-tag). Tetap aktif setelah .rs\n.kk on/off - Pemain tetap (ALBOTZ di K, KWINGZ di B, bertanda P) langsung ada di .list & .rk walau belum pik. Tetap ada setelah .rs, hilang hanya dengan .kk off\n.setkkk NAMA JUMLAH / .setkkb NAMA JUMLAH - Ganti pemain tetap .kk di sisi K / sisi B (per chat, tetap ada setelah .rs)Developer : @dlzzyyy"},
	"list": {Label: "🎯 Slot & List", Text: "🎯 Slot & List\n\n.list - Susun daftar K/B dari pik, dicek ke pin grup (P = nama ada di pin & jumlah cukup)\n.rk - Rekap total K & B dari .list, selisih, dan saldo seharusnya. Setelah .rk, sisi yang lebih besar (K atau B) tidak menerima pik baru. Bot juga mengirim ajakan sisi yang kurang, mis. \"B -50 ALL // ECER\". Pemain yang mengetik \"r\" membuat Roll Request (via bot, tombol Konfirm / Tolak); setelah Konfirm, pemain dipindah/masuk ke sisi kurang sebesar kekurangannya\n.rs - Reset .list chat ini untuk data baru (pik, sisi tertutup, dan aturan .rk ikut dibersihkan; status .on/.off, .kk, .alert tetap)\n.tf - Balas semua pemain bertanda titik (.) di .list dengan \"Tf Ganteng\"\n.ck - Tutup sisi K (pik K baru tidak dicatat)\n.cb - Tutup sisi B (pik B baru tidak dicatat)\n.ok - Buka semua: sisi K, sisi B, dan aturan setelah .rk (.ok k / .ok b = buka satu sisi)\n.h (reply pemain / .h <nama>) - Hapus pemain dari .list\n.tambah <jumlah> [k/b] (reply pemain / .tambah <nama> <jumlah>) - Tambah jumlah pik pemain di .list\n.kurang <jumlah> [k/b] (reply pemain / .kurang <nama> <jumlah>) - Kurangi jumlah pik; kalau jadi 0 pemain dihapus dari .list\n.font on - Semua pesan userbot jadi font tebal\n.font off - Kembali ke font normal (tanpa argumen = lihat status)\n.perak - Input satuan ribuan di chat ini: k10 = 10000, k10,9 = 10900, k3,6 = 3600, k1k / k1000 = 1000, k300 = 300 (tercatat di .list dan .rk). Berlaku juga untuk .sk dan .sb. kall / ball tetap mengikuti angka di pin apa adanya. Tetap aktif setelah .rs\n.nonperak - Input satuan biasa (bawaan): k10 = 10, k300 = 300\n.sk (reply pesan pemain berisi angka, atau .sk <jumlah>) - Catat pik K pemain itu, mis. reply \"50\" dengan .sk = K 50\n.sb (reply pesan pemain berisi angka, atau .sb <jumlah>) - Catat pik B pemain itu, mis. .sb 70 = B 7Developer : @dlzzyyy"},
	"pin": {Label: "📌 Pinned & Alias", Text: "📌 Pinned & Alias\n\n.p (reply pemain / .p <nama>) - Paksa tanda P di .list\n.c (reply pemain / .c <nama>) - Hilangkan tanda titik di .list\n.svown (reply / ID) - Bypass P-marker: pemain itu selalu bertanda P di .list, tidak perlu ada di pinned\n.svdelown (reply / ID) - Cabut bypass P-marker\n.sv <nama> <00/00> (reply pemain / nama di .list) - Simpan ke kontak, nama di .list ikut berganti\n.svsync [00/00] - Seperti .svslot, tapi pemain yang sudah tersimpan juga diperbarui namanya (penanda 00/00 lama dipertahankan)\n.svslot [00/00] - Simpan otomatis semua pemain di .list / yang menulis \"pik 20\" yang belum tersimpanDeveloper : @dlzzyyy"},
	"help": {Label: "📖 Bantuan", Text: "📖 Bantuan\n\nAlur singkat:\n1. Pin daftar saldo pemain di grup (satu baris: NAMA JUMLAH).\n2. Ketik .on (atau .akses) di grup supaya pik K/B dicatat.\n3. Ketik .list untuk melihat daftar K/B. P = nama ada di pin dan saldo cukup, titik (.) = belum cukup / tidak ada di pin.\n4. Ketik .rk untuk rekap K & B. Setelah selesai, ketik .rs untuk mulai data baru.\n\nTips:\n• Pemain bisa pik dengan \"K 50\", \"B 20\", atau \"kall\" / \"ball\" (seluruh saldo di pin).\n• .p / .c menimpa tanda P / titik per pemain; .svown membuat pemain selalu P.\n• .kk on = pemain tetap di K dan B, tetap ada setelah .rs.\n• Ketik .cmd untuk membuka menu ini lagi.Developer : @dlzzyyy"},
}

const BackLabel = "⬅️ Kembali"

const FullPrefix = "📋 Daftar Perintah\n\n"
